INSERT INTO "destinations" ("slug", "name", "name_hi", "category", "era", "locality", "address", "lat", "lng", "image", "summary", "why_visit", "history", "architecture", "facts", "sources", "hours", "fee", "rules", "facilities", "accessibility", "ticket_url", "ticket_provider", "unesco", "published", "sort_order")
VALUES ('red-fort', 'Red Fort', 'लाल किला', 'monument', 'Mughal', 'Old Delhi', 'Netaji Subhash Marg, Chandni Chowk, Old Delhi', 28.6562, 77.241, '/assets/monuments/red-fort-hero.jpg', 'The red sandstone fortress-palace of Shah Jahan''s capital, Shahjahanabad, and the stage of India''s Independence Day address.', 'Walk through Lahori Gate and Chatta Chowk into the heart of the Mughal capital: audience halls, pavilions and gardens that show how an empire staged power. It is also where the Prime Minister raises the national flag every 15 August, so it links Mughal Delhi to modern India.', 'Construction of the fort began in 1638 when Shah Jahan moved his capital from Agra to Delhi, and it was completed around 1648. The court lived here until the later Mughal decline; after 1857 the British used the fort as a garrison and altered many interior structures. Today it is part of the UNESCO-listed Red Fort Complex.', 'Octagonal plan with massive red sandstone walls, Lahori and Delhi gates, the Diwan-i-Aam and Diwan-i-Khas, and marble pavilions that blend Persian, Timurid and Indian traditions.', '["Construction began in 1638 and was largely complete by about 1648.","UNESCO World Heritage (Red Fort Complex, 2007).","The PM addresses the nation from its ramparts on Independence Day."]'::jsonb, '[{"title":"Red Fort Complex","publisher":"UNESCO World Heritage Centre","url":"https://whc.unesco.org/en/list/231"},{"title":"Archaeological Survey of India — monument listings","publisher":"Archaeological Survey of India","url":"https://asi.nic.in/","checked":null},{"title":"Wikipedia article (community-edited; cross-check with ASI/UNESCO)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Red_Fort","checked":null},{"title":"OpenStreetMap contributors","publisher":"OpenStreetMap","url":"https://www.openstreetmap.org/copyright","checked":null}]'::jsonb, 'Not verified in this app — confirm with the official provider before travelling.', 'Not verified in this app — confirm with the official provider before travelling.', 'Security screening at entry; carry-in restrictions apply.', 'Museums inside the complex, drinking water, restrooms (availability not verified).', 'Uneven historic surfaces; details not verified.', 'https://asi.payumoney.com/', 'ASI e-ticketing portal (external)', true, true, 1)
ON CONFLICT ("slug") DO UPDATE SET "image" = EXCLUDED."image", "summary" = EXCLUDED."summary";

INSERT INTO "destinations" ("slug", "name", "name_hi", "category", "era", "locality", "address", "lat", "lng", "image", "summary", "why_visit", "history", "architecture", "facts", "sources", "hours", "fee", "rules", "facilities", "accessibility", "ticket_url", "ticket_provider", "unesco", "published", "sort_order")
VALUES ('qutub-minar', 'Qutub Minar', 'क़ुतुब मीनार', 'monument', 'Delhi Sultanate', 'Mehrauli', 'Seth Sarai, Mehrauli, New Delhi', 28.5245, 77.1855, '/assets/monuments/qutub-minar-cinematic.jpg', 'A soaring 72.5-metre sandstone-and-marble minaret and the centrepiece of the earliest surviving monuments of the Delhi Sultanate.', 'Stand at the base of one of the tallest brick minarets in the world and read centuries of calligraphy on its fluted shaft. The surrounding complex — Quwwat-ul-Islam mosque, the Iron Pillar and Alai Darwaza — lets you see early Indo-Islamic architecture develop in one walk.', 'Qutb ud-Din Aibak began the tower around 1199; his successor Iltutmish added storeys, and later rulers including Firoz Shah Tughlaq repaired and extended it. The Quwwat-ul-Islam mosque beside it is among the earliest in northern India.', 'Five storeys with alternating angular and round flutes, projecting balconies, bands of Qur''anic inscriptions and red sandstone with marble in the upper levels.', '["Height about 72.5 metres.","Construction began c. 1199 under Qutb ud-Din Aibak.","UNESCO-listed with its monuments (1993).","The nearby Iron Pillar is widely dated to the Gupta period."]'::jsonb, '[{"title":"Qutb Minar and its Monuments, Delhi","publisher":"UNESCO World Heritage Centre","url":"https://whc.unesco.org/en/list/233"},{"title":"Archaeological Survey of India — monument listings","publisher":"Archaeological Survey of India","url":"https://asi.nic.in/","checked":null},{"title":"Wikipedia article (community-edited; cross-check with ASI/UNESCO)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Qutb_Minar","checked":null},{"title":"OpenStreetMap contributors","publisher":"OpenStreetMap","url":"https://www.openstreetmap.org/copyright","checked":null}]'::jsonb, 'Not verified in this app — confirm with the official provider before travelling.', 'Not verified in this app — confirm with the official provider before travelling.', 'Entry into the tower itself is not generally permitted — confirm on the official site.', 'Gardens and lawns, restrooms (not verified).', 'Not verified.', 'https://asi.payumoney.com/', 'ASI e-ticketing portal (external)', true, true, 2)
ON CONFLICT ("slug") DO UPDATE SET "image" = EXCLUDED."image", "summary" = EXCLUDED."summary";

INSERT INTO "destinations" ("slug", "name", "name_hi", "category", "era", "locality", "address", "lat", "lng", "image", "summary", "why_visit", "history", "architecture", "facts", "sources", "hours", "fee", "rules", "facilities", "accessibility", "ticket_url", "ticket_provider", "unesco", "published", "sort_order")
VALUES ('humayuns-tomb', 'Humayun''s Tomb', 'हुमायूँ का मकबरा', 'monument', 'Mughal', 'Nizamuddin', 'Mathura Road, Nizamuddin East, New Delhi', 28.5933, 77.2507, '/assets/monuments/humayun-tomb-atmosphere.jpg', 'The first garden-tomb on the Indian subcontinent, set in a charbagh and the architectural precursor of the Taj Mahal.', 'A calm, symmetrical garden complex where you can see how Persian garden planning met Indian craft. Combine it with Sunder Nursery and the Nizamuddin neighbourhood for a slow, rewarding half-day.', 'Commissioned by Humayun''s first wife Bega Begum, the tomb was built roughly between 1565 and 1572 under Akbar. The design is credited to the Persian architect Mirak Mirza Ghiyas. Later it sheltered Mughal royalty and, in 1857, the last Mughal emperor surrendered here.', 'Red sandstone with white marble inlay on a raised platform, a double dome, a four-part garden (charbagh) with water channels and arched alcoves.', '["Built c. 1565–1572.","UNESCO-listed in 1993.","Often described as the precursor to the Taj Mahal''s design."]'::jsonb, '[{"title":"Humayun''s Tomb, Delhi","publisher":"UNESCO World Heritage Centre","url":"https://whc.unesco.org/en/list/232"},{"title":"Archaeological Survey of India — monument listings","publisher":"Archaeological Survey of India","url":"https://asi.nic.in/","checked":null},{"title":"Wikipedia article (community-edited; cross-check with ASI/UNESCO)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Humayun''s_Tomb","checked":null},{"title":"OpenStreetMap contributors","publisher":"OpenStreetMap","url":"https://www.openstreetmap.org/copyright","checked":null}]'::jsonb, 'Not verified in this app — confirm with the official provider before travelling.', 'Not verified in this app — confirm with the official provider before travelling.', 'Follow site rules on photography and carry-in items as posted at the gate.', 'Gardens, restrooms (not verified).', 'Not verified.', 'https://asi.payumoney.com/', 'ASI e-ticketing portal (external)', true, true, 3)
ON CONFLICT ("slug") DO UPDATE SET "image" = EXCLUDED."image", "summary" = EXCLUDED."summary";

INSERT INTO "destinations" ("slug", "name", "name_hi", "category", "era", "locality", "address", "lat", "lng", "image", "summary", "why_visit", "history", "architecture", "facts", "sources", "hours", "fee", "rules", "facilities", "accessibility", "ticket_url", "ticket_provider", "unesco", "published", "sort_order")
VALUES ('india-gate', 'India Gate', 'इंडिया गेट', 'memorial', 'Colonial', 'Central Delhi', 'Kartavya Path, New Delhi', 28.6129, 77.2295, '/assets/monuments/india-gate-dusk.jpg', 'A 42-metre war memorial arch designed by Edwin Lutyens, honouring Indian soldiers who died in the First World War.', 'The city''s great evening gathering place: lit lawns, a ceremonial avenue and a clear view toward Rashtrapati Bhavan. Come near sunset and stay for the lights.', 'The foundation stone was laid in 1921 and the memorial inaugurated in 1931 as the All India War Memorial, commemorating soldiers of the British Indian Army who died in the First World War and the Third Anglo-Afghan War; their names are inscribed on the arch.', 'A triumphal arch of red and buff sandstone in Lutyens''s classical style; the Amar Jawan Jyoti was added near it after 1971, and the National War Memorial stands close by.', '["Designed by Edwin Lutyens; inaugurated 1931.","The arch is about 42 metres high.","Thousands of names of soldiers are inscribed on its walls."]'::jsonb, '[{"title":"Delhi Tourism — places to visit","publisher":"Delhi Tourism & Transportation Development Corp.","url":"https://delhitourism.gov.in/","checked":null},{"title":"Archaeological Survey of India — monument listings","publisher":"Archaeological Survey of India","url":"https://asi.nic.in/","checked":null},{"title":"Wikipedia article (community-edited; cross-check with ASI/UNESCO)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/India_Gate","checked":null},{"title":"OpenStreetMap contributors","publisher":"OpenStreetMap","url":"https://www.openstreetmap.org/copyright","checked":null}]'::jsonb, 'Not verified in this app — confirm with the official provider before travelling.', 'Believed free — not verified.', 'The area may close for ceremonies — follow local restrictions.', 'Open lawns, food vendors nearby.', 'Largely flat paved surroundings (not verified).', NULL, NULL, false, true, 4)
ON CONFLICT ("slug") DO UPDATE SET "image" = EXCLUDED."image", "summary" = EXCLUDED."summary";

INSERT INTO "destinations" ("slug", "name", "name_hi", "category", "era", "locality", "address", "lat", "lng", "image", "summary", "why_visit", "history", "architecture", "facts", "sources", "hours", "fee", "rules", "facilities", "accessibility", "ticket_url", "ticket_provider", "unesco", "published", "sort_order")
VALUES ('purana-qila', 'Purana Qila', 'पुराना किला', 'monument', 'Mughal & Suri', 'Central Delhi', 'Mathura Road, near Delhi Zoo, New Delhi', 28.6096, 77.2437, '/assets/monuments/purana-qila.jpg', 'A massive 16th-century fort on one of Delhi''s oldest continuously inhabited sites, linked to Humayun and Sher Shah Suri.', 'Atmospheric ramparts, the Qila-i-Kuhna mosque and a quiet lake make it one of Delhi''s most photogenic yet less crowded monuments.', 'Humayun began the fortified city of Din-Panah in the 1530s; after Sher Shah Suri defeated him, Sher Shah continued construction and built the Qila-i-Kuhna mosque and Sher Mandal.', 'Three gateways in rubble and red sandstone, high walls, the Qila-i-Kuhna mosque with pointed arches and Sher Mandal, an octagonal pavilion.', '["Associated with Humayun''s Din-Panah and Sher Shah Suri.","Qila-i-Kuhna mosque dates to the 1540s."]'::jsonb, '[{"title":"Archaeological Survey of India — monument listings","publisher":"Archaeological Survey of India","url":"https://asi.nic.in/","checked":null},{"title":"Delhi Tourism — places to visit","publisher":"Delhi Tourism & Transportation Development Corp.","url":"https://delhitourism.gov.in/","checked":null},{"title":"Wikipedia article (community-edited; cross-check with ASI/UNESCO)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Purana_Qila","checked":null},{"title":"OpenStreetMap contributors","publisher":"OpenStreetMap","url":"https://www.openstreetmap.org/copyright","checked":null}]'::jsonb, 'Not verified in this app — confirm with the official provider before travelling.', 'Not verified in this app — confirm with the official provider before travelling.', 'Check site rules at entry.', 'Boating on the adjoining lake has historically been available — not verified.', 'Not verified.', 'https://asi.payumoney.com/', 'ASI e-ticketing portal (external)', false, true, 5)
ON CONFLICT ("slug") DO UPDATE SET "image" = EXCLUDED."image", "summary" = EXCLUDED."summary";

INSERT INTO "destinations" ("slug", "name", "name_hi", "category", "era", "locality", "address", "lat", "lng", "image", "summary", "why_visit", "history", "architecture", "facts", "sources", "hours", "fee", "rules", "facilities", "accessibility", "ticket_url", "ticket_provider", "unesco", "published", "sort_order")
VALUES ('jama-masjid', 'Jama Masjid', 'जामा मस्जिद', 'religious', 'Mughal', 'Old Delhi', 'Meena Bazaar, Jama Masjid, Old Delhi', 28.6507, 77.2334, '/assets/monuments/jama-masjid-courtyard.jpg', 'One of India''s largest mosques, built by Shah Jahan, with a vast courtyard and views across Old Delhi.', 'Experience a living place of worship and a landmark of Shahjahanabad, with a courtyard that can hold thousands. The surrounding lanes of kebab shops and bazaars are part of the experience.', 'Commissioned by Shah Jahan and built between about 1650 and 1656, it was the principal mosque of his new capital.', 'Red sandstone and white marble, three great gateways, four towers and two 40-metre minarets with domes.', '["Built c. 1650–1656 under Shah Jahan.","An active mosque — visitors must dress modestly."]'::jsonb, '[{"title":"Archaeological Survey of India — monument listings","publisher":"Archaeological Survey of India","url":"https://asi.nic.in/","checked":null},{"title":"Delhi Tourism — places to visit","publisher":"Delhi Tourism & Transportation Development Corp.","url":"https://delhitourism.gov.in/","checked":null},{"title":"Wikipedia article (community-edited; cross-check with ASI/UNESCO)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Jama_Masjid,_Delhi","checked":null},{"title":"OpenStreetMap contributors","publisher":"OpenStreetMap","url":"https://www.openstreetmap.org/copyright","checked":null}]'::jsonb, 'Visiting is restricted around prayer times — timings not verified.', 'Believed free — not verified.', 'Modest clothing; remove footwear; restrictions around prayer times.', 'Footwear keeping nearby (not verified).', 'Steep steps at gates; not verified.', NULL, NULL, false, true, 6)
ON CONFLICT ("slug") DO UPDATE SET "image" = EXCLUDED."image", "summary" = EXCLUDED."summary";

INSERT INTO "destinations" ("slug", "name", "name_hi", "category", "era", "locality", "address", "lat", "lng", "image", "summary", "why_visit", "history", "architecture", "facts", "sources", "hours", "fee", "rules", "facilities", "accessibility", "ticket_url", "ticket_provider", "unesco", "published", "sort_order")
VALUES ('lodhi-garden', 'Lodhi Garden', 'लोधी गार्डन', 'garden', 'Sayyid & Lodi', 'Lodhi Road', 'Lodhi Road, New Delhi', 28.5931, 77.2197, '/assets/monuments/lodhi-garden.jpg', 'A landscaped park holding 15th–16th century tombs of the Sayyid and Lodi dynasties — Delhi''s favourite morning walk.', 'Free-flowing greenery with Sikandar Lodi''s tomb, Bara Gumbad and Sheesh Gumbad. Ideal for a slow walk, birdwatching and photography.', 'The tombs of the Sayyid and Lodi rulers date to the 15th and early 16th centuries. The area was landscaped as a public park in the 1930s, originally named after Lady Willingdon.', 'Square and octagonal tombs with domes, chhatris and traces of glazed tile decoration.', '["Contains Sikandar Lodi''s tomb (early 16th century).","Landscaped in the 1930s."]'::jsonb, '[{"title":"Archaeological Survey of India — monument listings","publisher":"Archaeological Survey of India","url":"https://asi.nic.in/","checked":null},{"title":"Delhi Tourism — places to visit","publisher":"Delhi Tourism & Transportation Development Corp.","url":"https://delhitourism.gov.in/","checked":null},{"title":"Wikipedia article (community-edited; cross-check with ASI/UNESCO)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Lodhi_Gardens","checked":null},{"title":"OpenStreetMap contributors","publisher":"OpenStreetMap","url":"https://www.openstreetmap.org/copyright","checked":null}]'::jsonb, 'Not verified in this app — confirm with the official provider before travelling.', 'Believed free — not verified.', 'Park rules apply.', 'Walking paths, benches.', 'Paved paths in many areas (not verified).', NULL, NULL, false, true, 7)
ON CONFLICT ("slug") DO UPDATE SET "image" = EXCLUDED."image", "summary" = EXCLUDED."summary";

INSERT INTO "destinations" ("slug", "name", "name_hi", "category", "era", "locality", "address", "lat", "lng", "image", "summary", "why_visit", "history", "architecture", "facts", "sources", "hours", "fee", "rules", "facilities", "accessibility", "ticket_url", "ticket_provider", "unesco", "published", "sort_order")
VALUES ('agrasen-ki-baoli', 'Agrasen ki Baoli', 'अग्रसेन की बावली', 'monument', 'Medieval (origins uncertain)', 'Connaught Place', 'Hailey Road, near Connaught Place, New Delhi', 28.6265, 77.2251, '/assets/monuments/agrasen-ki-baoli.jpg', 'A deep stepwell tucked between modern high-rises — a hidden pocket of medieval engineering in the city centre.', 'Descend its rows of arched niches into cool shade and see how Delhi once managed water. A short detour if you are around Connaught Place.', 'The stepwell is protected by the Archaeological Survey of India. Its exact construction date is uncertain; it is commonly described as medieval and associated by tradition with Maharaja Agrasen, with rebuilding in the Tughlaq or Lodi era according to some accounts.', 'Three levels of arched niches flanking a long flight of steps leading to a circular well.', '["ASI-protected monument.","The date and builder are debated — treat any single date with caution."]'::jsonb, '[{"title":"Archaeological Survey of India — monument listings","publisher":"Archaeological Survey of India","url":"https://asi.nic.in/","checked":null},{"title":"Wikipedia article (community-edited; cross-check with ASI/UNESCO)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Agrasen_ki_Baoli","checked":null},{"title":"OpenStreetMap contributors","publisher":"OpenStreetMap","url":"https://www.openstreetmap.org/copyright","checked":null}]'::jsonb, 'Not verified in this app — confirm with the official provider before travelling.', 'Not verified in this app — confirm with the official provider before travelling.', 'Do not enter the water; follow site staff instructions.', 'Not verified.', 'Many steps; not step-free.', NULL, NULL, false, true, 8)
ON CONFLICT ("slug") DO UPDATE SET "image" = EXCLUDED."image", "summary" = EXCLUDED."summary";

INSERT INTO "destinations" ("slug", "name", "name_hi", "category", "era", "locality", "address", "lat", "lng", "image", "summary", "why_visit", "history", "architecture", "facts", "sources", "hours", "fee", "rules", "facilities", "accessibility", "ticket_url", "ticket_provider", "unesco", "published", "sort_order")
VALUES ('safdarjung-tomb', 'Safdarjung''s Tomb', 'सफ़दरजंग का मकबरा', 'monument', 'Late Mughal', 'Lodhi Road', 'Safdarjung Airport Area, Aurobindo Marg, New Delhi', 28.5897, 77.2109, '/assets/monuments/safdarjung-tomb.jpg', 'A grand 18th-century garden tomb — one of the last great Mughal garden tombs in Delhi.', 'Compare it with Humayun''s Tomb: same charbagh idea, later and more ornate, with far fewer visitors.', 'Built in 1754 by Nawab Shuja-ud-Daula for his father Safdarjung, the Mughal viceroy of Awadh.', 'Marble dome over a sandstone-and-marble mausoleum within a walled charbagh with pavilions.', '["Built in 1754.","Often cited as the last garden tomb of the Mughal tradition in Delhi."]'::jsonb, '[{"title":"Archaeological Survey of India — monument listings","publisher":"Archaeological Survey of India","url":"https://asi.nic.in/","checked":null},{"title":"Delhi Tourism — places to visit","publisher":"Delhi Tourism & Transportation Development Corp.","url":"https://delhitourism.gov.in/","checked":null},{"title":"Wikipedia article (community-edited; cross-check with ASI/UNESCO)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Safdarjung''s_Tomb","checked":null},{"title":"OpenStreetMap contributors","publisher":"OpenStreetMap","url":"https://www.openstreetmap.org/copyright","checked":null}]'::jsonb, 'Not verified in this app — confirm with the official provider before travelling.', 'Not verified in this app — confirm with the official provider before travelling.', 'Check site rules at entry.', 'Gardens.', 'Not verified.', 'https://asi.payumoney.com/', 'ASI e-ticketing portal (external)', false, true, 9)
ON CONFLICT ("slug") DO UPDATE SET "image" = EXCLUDED."image", "summary" = EXCLUDED."summary";

INSERT INTO "destinations" ("slug", "name", "name_hi", "category", "era", "locality", "address", "lat", "lng", "image", "summary", "why_visit", "history", "architecture", "facts", "sources", "hours", "fee", "rules", "facilities", "accessibility", "ticket_url", "ticket_provider", "unesco", "published", "sort_order")
VALUES ('national-museum', 'National Museum', 'राष्ट्रीय संग्रहालय', 'museum', 'Modern', 'Janpath', 'Janpath, New Delhi', 28.6117, 77.2194, '/assets/monuments/national-museum.jpg', 'One of India''s largest museums, with collections spanning prehistory to the modern era.', 'A good rainy-day or midday-heat refuge: sculpture, miniature paintings, textiles, coins and archaeology that give context to every monument you visit.', 'Established in 1949 and moved to its present building in the late 1950s; it is administered by the Ministry of Culture.', 'A circular, multi-gallery modernist museum building.', '["Established in 1949.","Collections span archaeology, art, textiles and numismatics."]'::jsonb, '[{"title":"Delhi Tourism — places to visit","publisher":"Delhi Tourism & Transportation Development Corp.","url":"https://delhitourism.gov.in/","checked":null},{"title":"Wikipedia article (community-edited; cross-check with ASI/UNESCO)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/National_Museum,_New_Delhi","checked":null},{"title":"OpenStreetMap contributors","publisher":"OpenStreetMap","url":"https://www.openstreetmap.org/copyright","checked":null}]'::jsonb, 'Not verified in this app — confirm with the official provider before travelling.', 'Not verified in this app — confirm with the official provider before travelling.', 'Bag and photography rules apply.', 'Cafe and cloakroom (not verified).', 'Not verified.', 'https://nationalmuseumindia.gov.in/', 'National Museum official website (external)', false, true, 10)
ON CONFLICT ("slug") DO UPDATE SET "image" = EXCLUDED."image", "summary" = EXCLUDED."summary";

INSERT INTO "destinations" ("slug", "name", "name_hi", "category", "era", "locality", "address", "lat", "lng", "image", "summary", "why_visit", "history", "architecture", "facts", "sources", "hours", "fee", "rules", "facilities", "accessibility", "ticket_url", "ticket_provider", "unesco", "published", "sort_order")
VALUES ('lotus-temple', 'Lotus Temple', 'लोटस टेम्पल', 'religious', 'Modern', 'South Delhi', 'Lotus Temple Road, Kalkaji, New Delhi', 28.5535, 77.2588, '/assets/monuments/lotus-temple.jpg', 'A Bahá''í House of Worship shaped like a half-open lotus, open to people of all faiths.', 'One of the most visited buildings in the world relative to its size. Sit in the silent prayer hall — a rare quiet room in a loud city — and admire the petal architecture from outside at dusk.', 'Designed by Iranian-Canadian architect Fariborz Sahba and dedicated in 1986. The Bahá''í Faith has no clergy; the temple is open for silent prayer and meditation.', '27 free-standing marble ''petals'' arranged in clusters of three to form nine sides, around a circular prayer hall about 40 metres high.', '["Dedicated in 1986.","Open to all religions; silence is observed inside."]'::jsonb, '[{"title":"Delhi Tourism — places to visit","publisher":"Delhi Tourism & Transportation Development Corp.","url":"https://delhitourism.gov.in/","checked":null},{"title":"Wikipedia article (community-edited; cross-check with ASI/UNESCO)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Lotus_Temple","checked":null},{"title":"OpenStreetMap contributors","publisher":"OpenStreetMap","url":"https://www.openstreetmap.org/copyright","checked":null}]'::jsonb, 'Not verified in this app — confirm with the official provider before travelling.', 'Believed free — not verified.', 'Silence inside; no shoes; photography allowed outside only.', 'Information centre, gardens (not verified).', 'Not verified.', 'https://www.bahai.org.in/lotus-temple', 'Official temple information page (external)', false, true, 11)
ON CONFLICT ("slug") DO UPDATE SET "image" = EXCLUDED."image", "summary" = EXCLUDED."summary";

INSERT INTO "destinations" ("slug", "name", "name_hi", "category", "era", "locality", "address", "lat", "lng", "image", "summary", "why_visit", "history", "architecture", "facts", "sources", "hours", "fee", "rules", "facilities", "accessibility", "ticket_url", "ticket_provider", "unesco", "published", "sort_order")
VALUES ('akshardham', 'Swaminarayan Akshardham', 'अक्षरधाम', 'religious', 'Modern', 'East Delhi', 'NH 24, Akshardham Marg, Pandav Nagar, New Delhi', 28.6127, 77.2773, '/assets/monuments/akshardham.jpg', 'A vast modern Hindu temple complex with stone carvings, boat ride, IMAX film and fountain shows.', 'The scale of the hand-carved sandstone is remarkable, and the boat ride through 10,000 years of Indian history is a good introduction for families.', 'Opened in 2005, built by the Bochasanwasi Akshar Purushottam Swaminarayan Sanstha (BAPS). Much of the stonework was carved in Rajasthan.', 'Pink sandstone and white marble mandir with carved pillars, a central monument, fountains and exhibition halls.', '["Opened in 2005.","Entry to exhibitions is ticketed; check the official site for show timings."]'::jsonb, '[{"title":"Delhi Tourism — places to visit","publisher":"Delhi Tourism & Transportation Development Corp.","url":"https://delhitourism.gov.in/","checked":null},{"title":"Wikipedia article (community-edited; cross-check with ASI/UNESCO)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Akshardham_(Delhi)","checked":null},{"title":"OpenStreetMap contributors","publisher":"OpenStreetMap","url":"https://www.openstreetmap.org/copyright","checked":null}]'::jsonb, 'Not verified in this app — confirm with the official provider before travelling.', 'Not verified in this app — confirm with the official provider before travelling.', 'Phones, cameras and leather items are not allowed inside; lockers provided on site.', 'Lockers, food court (not verified).', 'Not verified.', 'https://akshardham.com/delhi/', 'Official Akshardham Delhi site (external)', false, true, 12)
ON CONFLICT ("slug") DO UPDATE SET "image" = EXCLUDED."image", "summary" = EXCLUDED."summary";

INSERT INTO "destinations" ("slug", "name", "name_hi", "category", "era", "locality", "address", "lat", "lng", "image", "summary", "why_visit", "history", "architecture", "facts", "sources", "hours", "fee", "rules", "facilities", "accessibility", "ticket_url", "ticket_provider", "unesco", "published", "sort_order")
VALUES ('gurudwara-bangla-sahib', 'Gurudwara Bangla Sahib', 'गुरुद्वारा बングला साहिब', 'religious', 'Sikh / Mughal era', 'Connaught Place', 'Ashoka Road, Connaught Place, New Delhi', 28.6264, 77.2092, '/assets/monuments/gurudwara-bangla-sahib.jpg', 'One of Delhi''s most important Sikh gurdwaras, with a sacred sarovar and the famous community kitchen (langar).', 'Visit at any time — the langar serves free meals to thousands daily regardless of religion. The complex includes a museum and the site of the eighth Sikh Guru''s residence.', 'The site is associated with Guru Har Krishan, the eighth Sikh Guru, who stayed here in 1664 during a smallpox outbreak in Delhi. The current building dates largely to the 1930s–40s rebuilding.', 'A white marble gurdwara with a golden dome, beside a large rectangular sarovar.', '["Associated with Guru Har Krishan (17th century).","Langar (community kitchen) open to all."]'::jsonb, '[{"title":"Delhi Tourism — places to visit","publisher":"Delhi Tourism & Transportation Development Corp.","url":"https://delhitourism.gov.in/","checked":null},{"title":"Wikipedia article (community-edited; cross-check with ASI/UNESCO)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Gurudwara_Bangla_Sahib","checked":null},{"title":"OpenStreetMap contributors","publisher":"OpenStreetMap","url":"https://www.openstreetmap.org/copyright","checked":null}]'::jsonb, 'Open early morning to late night — exact timings not verified.', 'Believed free — not verified.', 'Cover your head, remove shoes, wash hands before entering.', 'Langar, museum, guest rooms (not verified).', 'Not verified.', NULL, NULL, false, true, 13)
ON CONFLICT ("slug") DO UPDATE SET "image" = EXCLUDED."image", "summary" = EXCLUDED."summary";

INSERT INTO "destinations" ("slug", "name", "name_hi", "category", "era", "locality", "address", "lat", "lng", "image", "summary", "why_visit", "history", "architecture", "facts", "sources", "hours", "fee", "rules", "facilities", "accessibility", "ticket_url", "ticket_provider", "unesco", "published", "sort_order")
VALUES ('nizamuddin-dargah', 'Nizamuddin Dargah', 'निज़ामुद्दीन dargah', 'religious', 'Sufi, 14th c.', 'Nizamuddin', 'Nizamuddin West, New Delhi', 28.591, 77.2428, '/assets/monuments/nizamuddin-dargah.jpg', 'The shrine of Sufi saint Khwaja Nizamuddin Auliya, heart of Delhi''s qawwali and Sufi tradition.', 'Thursday evenings bring qawwali at the courtyard. The surrounding basti (neighbourhood) is one of Delhi''s oldest living areas.', 'The dargah was built over the saint''s grave in the late 14th century; the present marble structure was largely rebuilt in the 19th century by the British after the original was damaged.', 'White marble mausoleum with a dome, set in a crowded courtyard of smaller graves and dargah buildings.', '["Saint died in 1325; shrine dates to the late 14th century.","Qawwali sessions traditionally held on Thursday evenings."]'::jsonb, '[{"title":"Archaeological Survey of India — monument listings","publisher":"Archaeological Survey of India","url":"https://asi.nic.in/","checked":null},{"title":"Wikipedia article (community-edited; cross-check with ASI/UNESCO)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Nizamuddin_Dargah","checked":null},{"title":"OpenStreetMap contributors","publisher":"OpenStreetMap","url":"https://www.openstreetmap.org/copyright","checked":null}]'::jsonb, 'Not verified in this app — confirm with the official provider before travelling.', 'Believed free — not verified.', 'Modest dress; non-Muslims welcome but respectful conduct expected; photography rules vary inside.', 'Not verified.', 'Crowded, uneven lanes; not verified.', NULL, NULL, false, true, 14)
ON CONFLICT ("slug") DO UPDATE SET "image" = EXCLUDED."image", "summary" = EXCLUDED."summary";

INSERT INTO "destinations" ("slug", "name", "name_hi", "category", "era", "locality", "address", "lat", "lng", "image", "summary", "why_visit", "history", "architecture", "facts", "sources", "hours", "fee", "rules", "facilities", "accessibility", "ticket_url", "ticket_provider", "unesco", "published", "sort_order")
VALUES ('kalkaji-mandir', 'Kalkaji Mandir', 'कालकाजी मंदिर', 'religious', 'Ancient origins, rebuilt', 'South Delhi', 'Kalkaji, New Delhi', 28.5359, 77.2588, '/assets/monuments/kalkaji-mandir.jpg', 'A major Hindu temple dedicated to Goddess Kali, believed to stand on a site sacred since ancient times.', 'A living temple that draws huge crowds, especially on Tuesdays and during Navratri.', 'Local tradition links the site to the Mahabharata period; the present temple was largely rebuilt in the 18th century. The name ''Kalkaji'' derives from the goddess Kali.', 'A multi-storey temple complex around a sanctum with a tall shikhara.', '["Traditionally linked to ancient Delhi.","Rebuilt largely in the 18th century."]'::jsonb, '[{"title":"Delhi Tourism — places to visit","publisher":"Delhi Tourism & Transportation Development Corp.","url":"https://delhitourism.gov.in/","checked":null},{"title":"Wikipedia article (community-edited; cross-check with ASI/UNESCO)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Kalkaji_Temple","checked":null},{"title":"OpenStreetMap contributors","publisher":"OpenStreetMap","url":"https://www.openstreetmap.org/copyright","checked":null}]'::jsonb, 'Not verified in this app — confirm with the official provider before travelling.', 'Believed free — not verified.', 'Temple rules apply; leather items may be restricted.', 'Not verified.', 'Not verified.', NULL, NULL, false, true, 15)
ON CONFLICT ("slug") DO UPDATE SET "image" = EXCLUDED."image", "summary" = EXCLUDED."summary";

INSERT INTO "destinations" ("slug", "name", "name_hi", "category", "era", "locality", "address", "lat", "lng", "image", "summary", "why_visit", "history", "architecture", "facts", "sources", "hours", "fee", "rules", "facilities", "accessibility", "ticket_url", "ticket_provider", "unesco", "published", "sort_order")
VALUES ('chhatarpur-temple', 'Chhatarpur Temple', 'छतरपुर मंदिर', 'religious', 'Modern', 'South Delhi', 'Chhatarpur, Mehrauli-Gurgaon Road, New Delhi', 28.5102, 77.1854, '/assets/monuments/chhatarpur-temple.jpg', 'South Delhi''s largest temple complex, dedicated to Goddess Chhatar Maya (a form of Katyayani).', 'A sprawling complex of white marble buildings, gardens and a large pond — surprisingly quiet on weekdays.', 'Built in 1974 by Baba Gordhan Dass; the complex has grown into one of the largest temple premises in India.', 'White marble temple buildings in a large walled complex with gardens and a water tank.', '["Established 1974.","One of the largest temple complexes in India."]'::jsonb, '[{"title":"Delhi Tourism — places to visit","publisher":"Delhi Tourism & Transportation Development Corp.","url":"https://delhitourism.gov.in/","checked":null},{"title":"Wikipedia article (community-edited; cross-check with ASI/UNESCO)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Chhatarpur_Temple","checked":null},{"title":"OpenStreetMap contributors","publisher":"OpenStreetMap","url":"https://www.openstreetmap.org/copyright","checked":null}]'::jsonb, 'Not verified in this app — confirm with the official provider before travelling.', 'Believed free — not verified.', 'Temple rules apply.', 'Gardens, community kitchen (bhandara) on festival days.', 'Not verified.', NULL, NULL, false, true, 16)
ON CONFLICT ("slug") DO UPDATE SET "image" = EXCLUDED."image", "summary" = EXCLUDED."summary";

INSERT INTO "destinations" ("slug", "name", "name_hi", "category", "era", "locality", "address", "lat", "lng", "image", "summary", "why_visit", "history", "architecture", "facts", "sources", "hours", "fee", "rules", "facilities", "accessibility", "ticket_url", "ticket_provider", "unesco", "published", "sort_order")
VALUES ('tughlaqabad-fort', 'Tughlaqabad Fort', 'तугलकाबाद किला', 'monument', 'Delhi Sultanate', 'South Delhi', 'Tughlaqabad, New Delhi', 28.5247, 77.24, '/assets/monuments/tughlaqabad-fort.jpg', 'A vast ruined fortress built by Ghiyasuddin Tughlaq in the 1320s — Delhi''s third city.', 'Massive sloping rubble walls rising from the forest make it one of Delhi''s most dramatic ruins, and it is far quieter than Qutub Minar.', 'Ghiyasuddin Tughlaq built the fortified city of Tughlaqabad around 1321–1325. Legend says he forced Delhi''s citizens to help build it, and his son Muhammad bin Tughlaq later moved the capital away to Daulatabad.', 'Enormous sloping walls of rubble masonry, bastions, gateways and the remains of the palace area, with the adjacent Tughlaq Crescent lake.', '["Built c. 1321–1325 under Ghiyasuddin Tughlaq.","The adjoining village of Tughlaqabad grew inside/around the walls."]'::jsonb, '[{"title":"Archaeological Survey of India — monument listings","publisher":"Archaeological Survey of India","url":"https://asi.nic.in/","checked":null},{"title":"Wikipedia article (community-edited; cross-check with ASI/UNESCO)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Tughlaqabad_Fort","checked":null},{"title":"OpenStreetMap contributors","publisher":"OpenStreetMap","url":"https://www.openstreetmap.org/copyright","checked":null}]'::jsonb, 'Not verified in this app — confirm with the official provider before travelling.', 'Not verified in this app — confirm with the official provider before travelling.', 'Ruins — watch your step; no facilities on site (not verified).', 'Not verified.', 'Very uneven terrain; not suitable for wheelchairs.', 'https://asi.payumoney.com/', 'ASI e-ticketing portal (external)', false, true, 17)
ON CONFLICT ("slug") DO UPDATE SET "image" = EXCLUDED."image", "summary" = EXCLUDED."summary";

INSERT INTO "destinations" ("slug", "name", "name_hi", "category", "era", "locality", "address", "lat", "lng", "image", "summary", "why_visit", "history", "architecture", "facts", "sources", "hours", "fee", "rules", "facilities", "accessibility", "ticket_url", "ticket_provider", "unesco", "published", "sort_order")
VALUES ('feroz-shah-kotla', 'Feroz Shah Kotla', 'फिरोजシャह कोटला', 'monument', 'Delhi Sultanate', 'Central Delhi', 'Bahadur Shah Zafar Marg, near Feroz Shah Kotla Ground, New Delhi', 28.616, 77.2413, '/assets/monuments/feroz-shah-kotla.jpg', 'The fortified palace complex of Firoz Shah Tughlaq, famous for its Ashokan pillar.', 'See the 3rd-century-BCE Ashokan pillar that Firoz Shah had moved here, plus the mosque and stepped pyramid of his palace.', 'Firoz Shah Tughlaq built this fortified citadel (Kotla Firoz Shah) in the 1350s as his new city near the Yamuna. He moved an Ashokan pillar from Topra (Haryana) and Meerut to Delhi and installed one here in 1356.', 'A mosque with a stepped pyramid (pyramidal tower), a baoli (stepwell), and the tall Ashokan pillar with Brahmi and edict inscriptions.', '["Built in the 1350s under Firoz Shah Tughlaq.","The Ashokan pillar here carries edicts of Emperor Ashoka (3rd century BCE)."]'::jsonb, '[{"title":"Archaeological Survey of India — monument listings","publisher":"Archaeological Survey of India","url":"https://asi.nic.in/","checked":null},{"title":"Wikipedia article (community-edited; cross-check with ASI/UNESCO)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Feroz_Shah_Kotla","checked":null},{"title":"OpenStreetMap contributors","publisher":"OpenStreetMap","url":"https://www.openstreetmap.org/copyright","checked":null}]'::jsonb, 'Not verified in this app — confirm with the official provider before travelling.', 'Not verified in this app — confirm with the official provider before travelling.', 'Check site rules at entry.', 'Grounds around the stadium (not verified).', 'Not verified.', 'https://asi.payumoney.com/', 'ASI e-ticketing portal (external)', false, true, 18)
ON CONFLICT ("slug") DO UPDATE SET "image" = EXCLUDED."image", "summary" = EXCLUDED."summary";

INSERT INTO "destinations" ("slug", "name", "name_hi", "category", "era", "locality", "address", "lat", "lng", "image", "summary", "why_visit", "history", "architecture", "facts", "sources", "hours", "fee", "rules", "facilities", "accessibility", "ticket_url", "ticket_provider", "unesco", "published", "sort_order")
VALUES ('bara-gumbad', 'Bara Gumbad', 'बड़ा गुंबद', 'monument', 'Lodi', 'Lodhi Road', 'Lodhi Garden, Lodhi Road, New Delhi', 28.5916, 77.2388, '/assets/monuments/bara-gumbad.jpg', 'The largest tomb in Lodhi Garden — a massive Lodi-era domed structure beside a mosque.', 'Its scale dwarfs the other tombs in the garden; the adjoining mosque shows classic Lodi double-dome construction.', 'Built in the early 16th century during the Lodi period, though the exact occupant is debated — traditions associate it with Sikandar Lodi or a noble.', 'A huge square tomb with a massive double dome, thick walls and a mosque with three domes beside it, all in grey quartzite and plaster.', '["Early 16th century, Lodi period.","Traditionally associated with Sikandar Lodi (exact identity debated)."]'::jsonb, '[{"title":"Archaeological Survey of India — monument listings","publisher":"Archaeological Survey of India","url":"https://asi.nic.in/","checked":null},{"title":"Wikipedia article (community-edited; cross-check with ASI/UNESCO)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Bara_Gumbad","checked":null},{"title":"OpenStreetMap contributors","publisher":"OpenStreetMap","url":"https://www.openstreetmap.org/copyright","checked":null}]'::jsonb, 'Inside Lodhi Garden — see Lodhi Garden timings (not verified).', 'Believed free — not verified.', 'Park rules apply.', 'Lodhi Garden facilities.', 'Not verified.', NULL, NULL, false, true, 19)
ON CONFLICT ("slug") DO UPDATE SET "image" = EXCLUDED."image", "summary" = EXCLUDED."summary";

INSERT INTO "destinations" ("slug", "name", "name_hi", "category", "era", "locality", "address", "lat", "lng", "image", "summary", "why_visit", "history", "architecture", "facts", "sources", "hours", "fee", "rules", "facilities", "accessibility", "ticket_url", "ticket_provider", "unesco", "published", "sort_order")
VALUES ('parliament-house', 'Parliament House (Sansad Bhavan)', 'संसद भवन', 'civic', 'Colonial', 'Central Delhi', 'Sansad Marg, New Delhi', 28.6176, 77.209, '/assets/monuments/parliament-house.jpg', 'The circular seat of India''s Parliament, designed by Lutyens and Baker and inaugurated in 1927.', 'Even from outside, the circular colonnaded building is one of New Delhi''s most striking sights. Inside, visitors can tour the galleries with prior permission.', 'Built as the Legislative Assembly of British India; inaugurated in 1927. Since 1950 it has housed the Lok Sabha and Rajya Sabha. A new Parliament building nearby was inaugurated in 2023.', 'A circular building with 144 sandstone columns and a central hall; designed by Edwin Lutyens and Herbert Baker.', '["Inaugurated in 1927.","Visits to the galleries require advance permission — not verified here."]'::jsonb, '[{"title":"Delhi Tourism — places to visit","publisher":"Delhi Tourism & Transportation Development Corp.","url":"https://delhitourism.gov.in/","checked":null},{"title":"Wikipedia article (community-edited; cross-check with ASI/UNESCO)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Parliament_of_India","checked":null},{"title":"OpenStreetMap contributors","publisher":"OpenStreetMap","url":"https://www.openstreetmap.org/copyright","checked":null}]'::jsonb, 'Visitor access by prior booking only — details not verified.', 'Not verified in this app — confirm with the official provider before travelling.', 'Security screening; cameras and phones restricted; advance visitor pass required (not verified).', 'Museum and visitor facilities (not verified).', 'Not verified.', 'https://sansad.in/', 'Official Parliament visitor portal (external)', false, true, 20)
ON CONFLICT ("slug") DO UPDATE SET "image" = EXCLUDED."image", "summary" = EXCLUDED."summary";

INSERT INTO "destinations" ("slug", "name", "name_hi", "category", "era", "locality", "address", "lat", "lng", "image", "summary", "why_visit", "history", "architecture", "facts", "sources", "hours", "fee", "rules", "facilities", "accessibility", "ticket_url", "ticket_provider", "unesco", "published", "sort_order")
VALUES ('rashtrapati-bhavan', 'Rashtrapati Bhavan', 'राष्ट्रपति भवन', 'civic', 'Colonial', 'Central Delhi', 'Rajpath, New Delhi', 28.6144, 77.209, '/assets/monuments/rashtrapati-bhavan.jpg', 'The official residence of the President of India — a 330-room palace on Raisina Hill.', 'The Mughal Gardens are open to the public for a few weeks each year, and the Change of Guard ceremony is a popular free spectacle. The building itself is a masterpiece of Lutyens''s Delhi.', 'Designed by Edwin Lutyens and completed in 1929 as the Viceroy''s House; it became the President''s residence in 1950.', 'A vast red-and-cream sandstone palace with a central dome of 145 feet, colonnades and the Mughal Gardens.', '["Completed in 1929.","Has about 340 rooms.","Mughal Gardens open seasonally — dates not verified here."]'::jsonb, '[{"title":"Delhi Tourism — places to visit","publisher":"Delhi Tourism & Transportation Development Corp.","url":"https://delhitourism.gov.in/","checked":null},{"title":"Wikipedia article (community-edited; cross-check with ASI/UNESCO)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Rashtrapati_Bhavan","checked":null},{"title":"OpenStreetMap contributors","publisher":"OpenStreetMap","url":"https://www.openstreetmap.org/copyright","checked":null}]'::jsonb, 'Seasonal public access to gardens — dates not verified.', 'Not verified in this app — confirm with the official provider before travelling.', 'Advance online booking required for garden visits (not verified).', 'Museum complex inside (not verified).', 'Not verified.', 'https://visitrashtrapatibhavan.gov.in/', 'Official Rashtrapati Bhavan visitor portal (external)', false, true, 21)
ON CONFLICT ("slug") DO UPDATE SET "image" = EXCLUDED."image", "summary" = EXCLUDED."summary";

INSERT INTO "destinations" ("slug", "name", "name_hi", "category", "era", "locality", "address", "lat", "lng", "image", "summary", "why_visit", "history", "architecture", "facts", "sources", "hours", "fee", "rules", "facilities", "accessibility", "ticket_url", "ticket_provider", "unesco", "published", "sort_order")
VALUES ('raj-ghat', 'Raj Ghat', 'राज घाट', 'memorial', 'Modern', 'Central Delhi', 'Raj Ghat Marg, New Delhi', 28.6414, 77.25, '/assets/monuments/raj-ghat.jpg', 'The memorial of Mahatma Gandhi, on the banks of the Yamuna where he was cremated in 1948.', 'A simple black marble platform inscribed ''Hey Ram'', set in large gardens that also hold the samadhis of several prime ministers.', 'Gandhi was assassinated on 30 January 1948 and cremated here the next day. Raj Ghat and the surrounding memorial park were laid out afterward; memorials of other national leaders stand nearby.', 'A low black marble platform on a raised square, in open lawns; nearby samadhis of presidents and prime ministers.', '["Gandhi cremated here on 31 January 1948.","Open daily — timings not verified."]'::jsonb, '[{"title":"Delhi Tourism — places to visit","publisher":"Delhi Tourism & Transportation Development Corp.","url":"https://delhitourism.gov.in/","checked":null},{"title":"Wikipedia article (community-edited; cross-check with ASI/UNESCO)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Raj_Ghat","checked":null},{"title":"OpenStreetMap contributors","publisher":"OpenStreetMap","url":"https://www.openstreetmap.org/copyright","checked":null}]'::jsonb, 'Not verified in this app — confirm with the official provider before travelling.', 'Believed free — not verified.', 'Respectful conduct; photography allowed on the platform (not verified).', 'Gardens, nearby memorial museum (not verified).', 'Flat paved paths in most areas (not verified).', NULL, NULL, false, true, 22)
ON CONFLICT ("slug") DO UPDATE SET "image" = EXCLUDED."image", "summary" = EXCLUDED."summary";

INSERT INTO "destinations" ("slug", "name", "name_hi", "category", "era", "locality", "address", "lat", "lng", "image", "summary", "why_visit", "history", "architecture", "facts", "sources", "hours", "fee", "rules", "facilities", "accessibility", "ticket_url", "ticket_provider", "unesco", "published", "sort_order")
VALUES ('national-war-memorial', 'National War Memorial', 'राष्ट्र प्रशासी युद्ध मेमोरियल', 'memorial', 'Modern', 'Central Delhi', 'C-Hexagon, India Gate, New Delhi', 28.613, 77.2305, '/assets/monuments/national-war-memorial.jpg', 'India''s national memorial to soldiers killed in wars since independence, opened in 2019 beside India Gate.', 'A powerful, beautifully designed memorial: concentric rings of granite tablets with names, an eternal flame, and a covered infantry gallery.', 'Inaugurated in February 2019, it commemorates more than 25,000 Indian soldiers who died in wars and operations after 1947.', 'Four concentric circles — the Amar Chakra (eternal flame), Veerta Chakra, Tyag Chakra and Rakshak Chakra with granite tablets bearing names.', '["Inaugurated in 2019.","Commemorates soldiers martyred after 1947."]'::jsonb, '[{"title":"Delhi Tourism — places to visit","publisher":"Delhi Tourism & Transportation Development Corp.","url":"https://delhitourism.gov.in/","checked":null},{"title":"Wikipedia article (community-edited; cross-check with ASI/UNESCO)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/National_War_Memorial_(India)","checked":null},{"title":"OpenStreetMap contributors","publisher":"OpenStreetMap","url":"https://www.openstreetmap.org/copyright","checked":null}]'::jsonb, 'Not verified in this app — confirm with the official provider before travelling.', 'Believed free — not verified.', 'Security checks; respectful conduct.', 'Information centre (not verified).', 'Not verified.', NULL, NULL, false, true, 23)
ON CONFLICT ("slug") DO UPDATE SET "image" = EXCLUDED."image", "summary" = EXCLUDED."summary";

INSERT INTO "destinations" ("slug", "name", "name_hi", "category", "era", "locality", "address", "lat", "lng", "image", "summary", "why_visit", "history", "architecture", "facts", "sources", "hours", "fee", "rules", "facilities", "accessibility", "ticket_url", "ticket_provider", "unesco", "published", "sort_order")
VALUES ('national-railway-museum', 'National Rail Museum', 'राष्ट्रीय रेल संग्रहालय', 'museum', 'Modern', 'Shanti Nagar', 'Shanti Nagar, New Delhi', 28.6449, 77.2004, '/assets/monuments/national-railway-museum.jpg', 'India''s national railway museum with vintage locomotives, carriages and a working toy train.', 'Huge outdoor and indoor galleries: steam engines from the Raj era, the Fairy Queen (one of the world''s oldest working steam locomotives), royal saloons.', 'Established in 1977; it is run by the Ministry of Railways and holds one of Asia''s largest railway collections.', 'A museum campus of halls plus extensive outdoor yards with tracks and locomotives.', '["Established in 1977.","Houses the Fairy Queen steam locomotive (1855)."]'::jsonb, '[{"title":"Delhi Tourism — places to visit","publisher":"Delhi Tourism & Transportation Development Corp.","url":"https://delhitourism.gov.in/","checked":null},{"title":"Wikipedia article (community-edited; cross-check with ASI/UNESCO)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/National_Rail_Museum","checked":null},{"title":"OpenStreetMap contributors","publisher":"OpenStreetMap","url":"https://www.openstreetmap.org/copyright","checked":null}]'::jsonb, 'Not verified in this app — confirm with the official provider before travelling.', 'Not verified in this app — confirm with the official provider before travelling.', 'Photography rules; stay off tracks.', 'Cafeteria, toy train ride (ticketed, not verified).', 'Outdoor yards uneven (not verified).', 'https://indianrailwaymuseum.org/', 'Official museum website (external)', false, true, 24)
ON CONFLICT ("slug") DO UPDATE SET "image" = EXCLUDED."image", "summary" = EXCLUDED."summary";

INSERT INTO "destinations" ("slug", "name", "name_hi", "category", "era", "locality", "address", "lat", "lng", "image", "summary", "why_visit", "history", "architecture", "facts", "sources", "hours", "fee", "rules", "facilities", "accessibility", "ticket_url", "ticket_provider", "unesco", "published", "sort_order")
VALUES ('ngma', 'National Gallery of Modern Art', 'नेशनल गैलरी ऑफ मॉडर्न आर्ट', 'museum', 'Modern', 'Near India Gate', 'Jaipur House, India Gate, New Delhi', 28.6188, 77.2346, '/assets/monuments/ngma.jpg', 'India''s premier modern-art museum, housed in the former Jaipur House palace near India Gate.', 'Strong collection of Indian modernists — Tagore, Amrita Sher-Gil, the Bombay Progressives — plus a sculpture garden.', 'Established in 1954 and moved to Jaipur House in 1960s; administered by the Ministry of Culture.', 'The early-20th-century Jaipur House palace with added gallery wings and a sculpture garden.', '["Established 1954.","Holds over 14,000 works (not verified)."]'::jsonb, '[{"title":"Delhi Tourism — places to visit","publisher":"Delhi Tourism & Transportation Development Corp.","url":"https://delhitourism.gov.in/","checked":null},{"title":"Wikipedia article (community-edited; cross-check with ASI/UNESCO)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/National_Gallery_of_Modern_Art,_New_Delhi","checked":null},{"title":"OpenStreetMap contributors","publisher":"OpenStreetMap","url":"https://www.openstreetmap.org/copyright","checked":null}]'::jsonb, 'Not verified in this app — confirm with the official provider before travelling.', 'Not verified in this app — confirm with the official provider before travelling.', 'No bags at some galleries; photography restrictions apply.', 'Cafe (not verified).', 'Not verified.', 'https://ngmaindia.gov.in/', 'NGMA official website (external)', false, true, 25)
ON CONFLICT ("slug") DO UPDATE SET "image" = EXCLUDED."image", "summary" = EXCLUDED."summary";

INSERT INTO "destinations" ("slug", "name", "name_hi", "category", "era", "locality", "address", "lat", "lng", "image", "summary", "why_visit", "history", "architecture", "facts", "sources", "hours", "fee", "rules", "facilities", "accessibility", "ticket_url", "ticket_provider", "unesco", "published", "sort_order")
VALUES ('indira-gandhi-memorial', 'Indira Gandhi Memorial', 'इंदिरा गांधी स्मृति', 'museum', 'Modern', 'Safdarjung Road', '1 Safdarjung Road, New Delhi', 28.5872, 77.2141, '/assets/monuments/indira-gandhi-memorial.jpg', 'The former residence of Prime Minister Indira Gandhi, now a memorial and museum at 1 Safdarjung Road.', 'Walk the bungalow and gardens where she lived; the conservatory holds her personal effects and photographs.', 'Indira Gandhi lived here from the 1960s until her assassination in 1984. The house was converted into a memorial open to the public.', 'A bungalow set in large gardens; the memorial preserves rooms and a garden with a glass conservatory.', '["Residence from the 1960s; she was assassinated here in 1984.","Open to visitors (timings not verified)."]'::jsonb, '[{"title":"Delhi Tourism — places to visit","publisher":"Delhi Tourism & Transportation Development Corp.","url":"https://delhitourism.gov.in/","checked":null},{"title":"Wikipedia article (community-edited; cross-check with ASI/UNESCO)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Indira_Gandhi_Memorial","checked":null},{"title":"OpenStreetMap contributors","publisher":"OpenStreetMap","url":"https://www.openstreetmap.org/copyright","checked":null}]'::jsonb, 'Not verified in this app — confirm with the official provider before travelling.', 'Believed free — not verified.', 'Security checks; photography restrictions inside.', 'Museum, garden (not verified).', 'Not verified.', NULL, NULL, false, true, 26)
ON CONFLICT ("slug") DO UPDATE SET "image" = EXCLUDED."image", "summary" = EXCLUDED."summary";

INSERT INTO "destinations" ("slug", "name", "name_hi", "category", "era", "locality", "address", "lat", "lng", "image", "summary", "why_visit", "history", "architecture", "facts", "sources", "hours", "fee", "rules", "facilities", "accessibility", "ticket_url", "ticket_provider", "unesco", "published", "sort_order")
VALUES ('teen-murti-house', 'Teen Murti House', 'तीन मूर्ति भवन', 'museum', 'Colonial', 'Teen Murti Marg', 'Teen Murti Marg, New Delhi', 28.6065, 77.2073, '/assets/monuments/teen-murti-house.jpg', 'The former residence of India''s first Prime Minister, Jawaharlal Nehru, now a memorial museum.', 'The library and study where Nehru lived for 17 years are preserved, with his personal belongings and gifts from world leaders.', 'Nehru lived here from 1947 until his death in 1964. It was converted into the Nehru Memorial Museum and Library.', 'A large colonial bungalow with extensive library wings, set in landscaped grounds; the planetarium stands nearby.', '["Nehru''s residence 1947–1964.","Now the Nehru Memorial Museum & Library."]'::jsonb, '[{"title":"Delhi Tourism — places to visit","publisher":"Delhi Tourism & Transportation Development Corp.","url":"https://delhitourism.gov.in/","checked":null},{"title":"Wikipedia article (community-edited; cross-check with ASI/UNESCO)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Teen_Murti","checked":null},{"title":"OpenStreetMap contributors","publisher":"OpenStreetMap","url":"https://www.openstreetmap.org/copyright","checked":null}]'::jsonb, 'Not verified in this app — confirm with the official provider before travelling.', 'Not verified in this app — confirm with the official provider before travelling.', 'Photography restrictions inside (not verified).', 'Library, planetarium nearby.', 'Not verified.', 'https://nehru-memorial-museum-lib.org/', 'Official Nehru Memorial website (external)', false, true, 27)
ON CONFLICT ("slug") DO UPDATE SET "image" = EXCLUDED."image", "summary" = EXCLUDED."summary";

INSERT INTO "destinations" ("slug", "name", "name_hi", "category", "era", "locality", "address", "lat", "lng", "image", "summary", "why_visit", "history", "architecture", "facts", "sources", "hours", "fee", "rules", "facilities", "accessibility", "ticket_url", "ticket_provider", "unesco", "published", "sort_order")
VALUES ('hauz-khas-village', 'Hauz Khas Village', 'हौज खास गांव', 'hidden', 'Sultanate to present', 'Hauz Khas', 'Hauz Khas, New Delhi', 28.5534, 77.1998, '/assets/monuments/hauz-khas-village.jpg', 'A medieval village around a 14th-century reservoir, now Delhi''s village of galleries, cafes and boutiques.', 'Wander the lanes around the Hauz Khas lake, duck into art galleries and rooftop cafes, and see the ruins of the old madrasa and tomb of Allauddin Khilji''s era within the village.', 'Alauddin Khilji built the reservoir (Hauz Khas) and a madrasa here in the early 14th century, creating the fortified city of Siri''s successor settlements; the village grew around the tank over centuries.', 'A village of narrow lanes, monuments (tomb of Sayyid/scholars), stepwells and modern galleries around a water tank.', '["Reservoir built by Alauddin Khilji (early 14th century).","Today a heritage village of cafes and galleries."]'::jsonb, '[{"title":"Archaeological Survey of India — monument listings","publisher":"Archaeological Survey of India","url":"https://asi.nic.in/","checked":null},{"title":"Delhi Tourism — places to visit","publisher":"Delhi Tourism & Transportation Development Corp.","url":"https://delhitourism.gov.in/","checked":null},{"title":"Wikipedia article (community-edited; cross-check with ASI/UNESCO)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Hauz_Khas_Village","checked":null},{"title":"OpenStreetMap contributors","publisher":"OpenStreetMap","url":"https://www.openstreetmap.org/copyright","checked":null}]'::jsonb, 'Not verified in this app — confirm with the official provider before travelling.', 'Believed free — not verified.', 'Village lanes — respect residents.', 'Cafes, galleries, boutiques.', 'Narrow uneven lanes.', NULL, NULL, false, true, 28)
ON CONFLICT ("slug") DO UPDATE SET "image" = EXCLUDED."image", "summary" = EXCLUDED."summary";

INSERT INTO "destinations" ("slug", "name", "name_hi", "category", "era", "locality", "address", "lat", "lng", "image", "summary", "why_visit", "history", "architecture", "facts", "sources", "hours", "fee", "rules", "facilities", "accessibility", "ticket_url", "ticket_provider", "unesco", "published", "sort_order")
VALUES ('garden-of-five-senses', 'Garden of Five Senses', 'पंच सेन्स का गार्डन', 'garden', 'Modern', 'Mehrauli', 'Saidul Ajaib Village, Mehrauli, New Delhi', 28.7047, 77.188, '/assets/monuments/garden-of-five-senses.jpg', 'A scented, landscaped garden near the Qutub area that hosts concerts and craft bazaars.', 'A pleasant sensory garden with bamboo courts, herb and flower beds; it hosts cultural festivals and the annual Garden Tourism Festival (dates not verified).', 'Developed by Delhi Tourism in the 2000s on land near Saidul Ajaib village, designed for accessibility and sensory experience.', 'Themed garden sections — fragrance garden, bamboo court, herb garden, solar garden — with water features.', '["Developed in the 2000s.","Hosts cultural events and fairs (schedules not verified)."]'::jsonb, '[{"title":"Delhi Tourism — places to visit","publisher":"Delhi Tourism & Transportation Development Corp.","url":"https://delhitourism.gov.in/","checked":null},{"title":"Wikipedia article (community-edited; cross-check with ASI/UNESCO)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Garden_of_Five_Senses","checked":null},{"title":"OpenStreetMap contributors","publisher":"OpenStreetMap","url":"https://www.openstreetmap.org/copyright","checked":null}]'::jsonb, 'Not verified in this app — confirm with the official provider before travelling.', 'Not verified in this app — confirm with the official provider before travelling.', 'Park rules apply.', 'Amphitheatre, food stalls during events (not verified).', 'Designed to be wheelchair-friendly (not verified).', NULL, NULL, false, true, 29)
ON CONFLICT ("slug") DO UPDATE SET "image" = EXCLUDED."image", "summary" = EXCLUDED."summary";

INSERT INTO "destinations" ("slug", "name", "name_hi", "category", "era", "locality", "address", "lat", "lng", "image", "summary", "why_visit", "history", "architecture", "facts", "sources", "hours", "fee", "rules", "facilities", "accessibility", "ticket_url", "ticket_provider", "unesco", "published", "sort_order")
VALUES ('buddha-jayanti-park', 'Buddha Jayanti Park', 'बुद्ध जयन्ति पार्क', 'garden', 'Modern', 'Ridge', 'Vandana Chowk, Ridge, New Delhi', 28.6255, 77.1871, '/assets/monuments/buddha-jayanti-park.jpg', 'A large park on the Delhi Ridge with a golden Buddha statue, built to mark 2,500 years of Buddhism.', 'A green ridge-top escape near Connaught Place with a gilded Buddha in dhyana mudra and walking trails through native forest.', 'Laid out in 1956 to commemorate 2,500 years of the Buddha''s enlightenment; the Buddha statue was gifted by Japan.', 'A golden Buddha statue on a pedestal in a landscaped park within the protected Delhi Ridge forest.', '["Created in 1956 for the Buddha''s 2,500th Jayanti.","Statue gifted by the people of Japan."]'::jsonb, '[{"title":"Delhi Tourism — places to visit","publisher":"Delhi Tourism & Transportation Development Corp.","url":"https://delhitourism.gov.in/","checked":null},{"title":"Wikipedia article (community-edited; cross-check with ASI/UNESCO)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Buddha_Jayanti_Park","checked":null},{"title":"OpenStreetMap contributors","publisher":"OpenStreetMap","url":"https://www.openstreetmap.org/copyright","checked":null}]'::jsonb, 'Not verified in this app — confirm with the official provider before travelling.', 'Believed free — not verified.', 'Park rules; the Ridge is a protected forest area.', 'Walking trails (not verified).', 'Some paved paths (not verified).', NULL, NULL, false, true, 30)
ON CONFLICT ("slug") DO UPDATE SET "image" = EXCLUDED."image", "summary" = EXCLUDED."summary";

